uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float offset : 0.0 .. 1.0 = 0.0;
uniform float width : 0.02 .. 0.5 = 0.12;
uniform vec3 red : color = 1.0, 0.0, 0.0;
uniform vec3 blue : color = 0.0, 0.2, 1.0;
uniform vec3 dark : color = 0.0, 0.0, 0.0;

state float phase;
state float spin;

void update() {
  phase = fract(phase + dt * speed);
  spin = fract(spin + dt * speed * 0.5);
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed y = fixed(led.pos.y);
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed rot = sin(fixed(spin * 6.2832)) * fixed(0.5) + fixed(0.5);
  fixed band = smoothstep(fixed(width), fixed(0.0), abs(fixed(fract(s - phase)) - fixed(0.5)));
  fixed blueBand = step(fixed(fract(ang + rot)), fixed(0.0)) * fixed(1.0);
  fixed redBand = step(fixed(1.0 - fract(ang + rot)), fixed(0.0)) * fixed(1.0);
  fixed col = mix(fixed(0.0), fixed(1.0), band);
  fixed r = redBand * col;
  fixed g = fixed(0.0);
  fixed b = blueBand * col;
  return mix(dark, mix(red, blue, fixed(b)), fixed(r));
}
